const markResearchDocumentUploadFailed = `-- name: MarkResearchDocumentUploadFailed :execrows
update public.research_documents document
set
  status = 'failed',
  error_code = $1,
  error_message = 'The document could not be stored. Retry the upload.'
from public.research_workspaces workspace
where document.id = $2
  and document.workspace_id = $3
  and workspace.id = document.workspace_id
  and workspace.user_id = $4
`

type MarkResearchDocumentUploadFailedParams struct {
	ErrorCode   pgtype.Text `json:"error_code"`
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UserID      pgtype.UUID `json:"user_id"`
}

func (q *Queries) MarkResearchDocumentUploadFailed(ctx context.Context, arg MarkResearchDocumentUploadFailedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markResearchDocumentUploadFailed,
		arg.ErrorCode,
		arg.ID,
		arg.WorkspaceID,
		arg.UserID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

